import{_ as e,o as n,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image%20(84).CSmr4PEs.png",i="/assets/image%20(85).C2k3Dpeb.png",r="/assets/image%20(87).CMyMMA-W.png",l="/assets/image%20(86).em8qyBiK.png",u="/assets/image%20(88).CPoA8QZd.png",p="/assets/image%20(89).B4rylWH6.png",d="/assets/image%20(90).DqixfSVe.png",b=JSON.parse('{"title":"N8N","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/n8n.md","filePath":"trading-platform/n8n.md"}'),g={name:"trading-platform/n8n.md"};function h(c,t,f,m,y,q){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="n8n" tabindex="-1">N8N <a class="header-anchor" href="#n8n" aria-label="Permalink to &quot;N8N&quot;">​</a></h1><p>n8n is a <strong>workflow automation tool</strong> that allows users to create automated workflows connecting different apps, APIs, and services without needing extensive coding knowledge. It is an open-source, self-hostable alternative to Zapier, Make, and other automation tools.</p><p>With n8n, traders can create workflows that:</p><ul><li>Fetch data from APIs</li><li>Process and transform data</li><li>Automate trading tasks</li><li>Integrate with trading platforms, brokers, databases, and messaging services</li></ul><h3 id="integrating-with-n8n-for-scheduled-order-placement" tabindex="-1">Integrating with n8n for Scheduled Order Placement <a class="header-anchor" href="#integrating-with-n8n-for-scheduled-order-placement" aria-label="Permalink to &quot;Integrating with n8n for Scheduled Order Placement&quot;">​</a></h3><p><br> This section guides you through creating a workflow in n8n, a powerful open-source workflow automation tool, to automatically place orders in Tradeboard at a scheduled time. We&#39;ll use the example of placing a short straddle on NIFTY options at 9:20 AM IST every day.</p><br><figure><img src="'+a+`" alt=""><figcaption></figcaption></figure><p><strong>Prerequisites:</strong></p><ul><li><strong>Tradeboard:</strong> You must have Tradeboard installed and running in <a href="http://127.0.0.1:5000/" target="_blank" rel="noreferrer">http://127.0.0.1:5000/</a>. Ensure your broker is properly configured within Tradeboard.</li><li>Install NodeJS as n8n backend relies on <strong>Node.js runtime</strong> to execute workflows, handle API calls, and manage automation.</li><li><strong>n8n:</strong> n8n should be installed and running. </li><li><strong>Tradeboard API Key:</strong> You&#39;ll need the Tradeboard API key generated on the API Key page of the Tradeboard dashboard. This is what the workflow sends in the <code>apikey</code> field. It is not your broker&#39;s API key or API secret.</li><li><strong>Basic Understanding of Cron Expressions:</strong> <a href="https://docs.n8n.io/integrations/builtin/core-nodes/n8n-nodes-base.scheduletrigger/#custom-cron-interval" target="_blank" rel="noreferrer">Cron expressions</a> are used to define schedules. We&#39;ll provide the specific expression you need, but it&#39;s helpful to have a basic understanding.</li></ul><h4 id="how-to-start-n8n-on-windows" tabindex="-1"><strong>How to Start n8n on Windows</strong> <a class="header-anchor" href="#how-to-start-n8n-on-windows" aria-label="Permalink to &quot;**How to Start n8n on Windows**&quot;">​</a></h4><p>To start n8n on Windows, follow these steps:</p><hr><h3 id="_1-install-node-js" tabindex="-1"><strong>1. Install Node.js</strong> <a class="header-anchor" href="#_1-install-node-js" aria-label="Permalink to &quot;**1. Install Node.js**&quot;">​</a></h3><p>Since n8n runs on <strong>Node.js</strong>, you need to install it first.</p><ol><li><p><strong>Download Node.js</strong> from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js official website</a></p></li><li><p><strong>Install the LTS (Long-Term Support) version</strong> (recommended for stability).</p></li><li><p><strong>Verify installation</strong> by opening Command Prompt (CMD) and running:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>If installed correctly, you will see the version numbers.</p></li></ol><hr><h3 id="_2-install-n8n" tabindex="-1"><strong>2. Install n8n</strong> <a class="header-anchor" href="#_2-install-n8n" aria-label="Permalink to &quot;**2. Install n8n**&quot;">​</a></h3><p>After Node.js is installed, you can install n8n using <strong>npm</strong>:</p><ol><li><p>Open <strong>Command Prompt (CMD)</strong> as Administrator.</p></li><li><p>Run the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> n8n</span></span></code></pre></div><p>This will install n8n globally on your system.</p></li><li><p>Check if n8n is installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">n8n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>If installed correctly, you will see the version number.</p></li></ol><hr><h3 id="_3-start-n8n" tabindex="-1"><strong>3. Start n8n</strong> <a class="header-anchor" href="#_3-start-n8n" aria-label="Permalink to &quot;**3. Start n8n**&quot;">​</a></h3><p>Once installed, start n8n with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">n8n</span></span></code></pre></div><p>This will start the n8n server. You should see logs like:</p><figure><img src="`+i+'" alt=""><figcaption></figcaption></figure><h4 id="access-n8n-in-browser" tabindex="-1"><strong>Access n8n in Browser</strong> <a class="header-anchor" href="#access-n8n-in-browser" aria-label="Permalink to &quot;**Access n8n in Browser**&quot;">​</a></h4><p>Open your browser and go to:<br><strong><a href="http://localhost:5678/" target="_blank" rel="noreferrer">http://localhost:5678/</a></strong></p><p>Now you can start creating workflows.</p><p><strong>Workflow Setup:</strong></p><p><strong>1. Create a New Workflow in n8n</strong></p><ul><li>Open your n8n instance in your browser (typically <a href="http://localhost:5678" target="_blank" rel="noreferrer">http://localhost:5678</a>).</li><li>Click the &quot;+&quot; button or &quot;Create Workflow&quot; option to start a new, blank workflow.</li></ul><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><p><strong>2. Add and Configure the Schedule Trigger</strong></p><ul><li>This node will be the starting point of our workflow, initiating the order placement at the specified time.</li><li>Click the &quot;+&quot; button to add the first node.</li><li>Search for &quot;Schedule Trigger&quot; and select it.</li><li>Select the &quot;Custom(Cron)&quot; as trigger interval from the options.</li><li>In the <strong>Expression</strong> field, enter the following Cron expression: 0 20 9 * * *</li><li><strong>Explanation of the Cron Expression:</strong><ul><li>0: Seconds (set to 0)</li><li>20: Minute (set to 20 for 9:20 AM)</li><li>9: Hour (set to 9 for 9:00 AM in 24-hour format)</li><li>*: Day of the Month (any day)</li><li>*: Month (any month)</li><li>*: Day of the Week (any day of the week)</li></ul></li></ul><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><ul><li><strong>Important: Timezone:</strong> By default, n8n uses UTC time. To ensure the trigger fires at 9:20 AM <em>Indian Standard Time (IST)</em>, you <strong>must</strong> set the timezone. <ul><li>Click on Settings</li><li>Click on n8n settings</li><li>Under general settings.</li><li>Select Timezone : &quot;Asia/Kolkata&quot;</li></ul></li></ul><figure><img src="'+u+`" alt=""><figcaption></figcaption></figure><p><strong>3. Add the First HTTP Request Node (SELL NIFTY Call Option)</strong></p><ul><li>Click the &quot;+&quot; button to the right of the &quot;Schedule Trigger&quot; node to add a new node.</li><li>Search for &quot;HTTP Request&quot; and select it.</li><li>Configure the node as follows: <ul><li><strong>Method:</strong> POST</li><li><strong>URL:</strong> <a href="http://127.0.0.1:5000/api/v1/placeorder" target="_blank" rel="noreferrer">http://127.0.0.1:5000/api/v1/placeorder</a> (This assumes Tradeboard is running on your local machine. Adjust if you&#39;re using a different URL.)</li><li><strong>Authentication:</strong> None. Tradeboard does not use HTTP authentication on <code>/api/v1/*</code>. It authenticates the request from the <code>apikey</code> field inside the JSON body, so leave n8n&#39;s own authentication set to None.</li><li><strong>Send Body:</strong> Check this box.</li><li><strong>Body Content Type:</strong> JSON</li><li><strong>Specify Body:</strong> Choose Using JSON</li><li><strong>JSON:</strong> Paste the following, replacing &quot;YOUR_TRADEBOARD_API_KEY&quot; with your actual API key:</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;apikey&quot;: &quot;YOUR_TRADEBOARD_API_KEY&quot;,</span></span>
<span class="line"><span>    &quot;strategy&quot;: &quot;Test Strategy&quot;,</span></span>
<span class="line"><span>    &quot;symbol&quot;: &quot;NIFTY06MAR2522100CE&quot;,</span></span>
<span class="line"><span>    &quot;exchange&quot;: &quot;NFO&quot;,</span></span>
<span class="line"><span>    &quot;action&quot;: &quot;SELL&quot;,</span></span>
<span class="line"><span>    &quot;pricetype&quot;: &quot;MARKET&quot;,</span></span>
<span class="line"><span>    &quot;product&quot;: &quot;MIS&quot;,</span></span>
<span class="line"><span>    &quot;quantity&quot;: &quot;75&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><figure><img src="`+p+`" alt=""><figcaption></figcaption></figure><ul><li><strong>Important Notes:</strong><ul><li>YOUR_TRADEBOARD_API_KEY: Replace this with your Tradeboard API key.</li><li>strategy: You can name your strategy anything you like (e.g., &quot;MyStraddleStrategy&quot;). This helps you identify the source of the order within Tradeboard.</li><li>symbol: Ensure this is the correct symbol for the NIFTY call option with the desired expiry and strike price. Double-check this!</li><li>exchange: Use &quot;NFO&quot; for NSE options.</li><li>action: &quot;SELL&quot; for the short straddle.</li><li>pricetype: &quot;MARKET&quot; for a market order.</li><li>product: &quot;MIS&quot; for intraday trading.</li><li>quantity: Total units, not lots. Set it to a whole multiple of the contract lot size. The example uses &quot;75&quot;, one NIFTY lot at the time of writing. Confirm the current lot size before you go live.</li></ul></li></ul><p><strong>4. Add the Second HTTP Request Node (SELL NIFTY Put Option)</strong></p><ul><li>Click the &quot;+&quot; button again to add another HTTP Request node. We need a separate request for the put option. Connect the same cron node created to the second HTTP request also.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;apikey&quot;: &quot;YOUR_TRADEBOARD_API_KEY&quot;,</span></span>
<span class="line"><span>    &quot;strategy&quot;: &quot;Test Strategy&quot;,</span></span>
<span class="line"><span>    &quot;symbol&quot;: &quot;NIFTY06MAR2522100PE&quot;,</span></span>
<span class="line"><span>    &quot;exchange&quot;: &quot;NFO&quot;,</span></span>
<span class="line"><span>    &quot;action&quot;: &quot;SELL&quot;,</span></span>
<span class="line"><span>    &quot;pricetype&quot;: &quot;MARKET&quot;,</span></span>
<span class="line"><span>    &quot;product&quot;: &quot;MIS&quot;,</span></span>
<span class="line"><span>    &quot;quantity&quot;: &quot;75&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>5. Save and Activate</strong></p><ul><li>Click &quot;Save&quot; in the top right corner to save your workflow.</li><li>Click the &quot;Active&quot; toggle switch in the top-right corner. It should turn green, indicating that the workflow is now active.</li></ul><figure><img src="`+d+'" alt=""><figcaption></figcaption></figure><p><strong>6. Test (Optional, but Highly Recommended!)</strong></p><ul><li><strong>Important:</strong> Before testing with the schedule, use the &quot;Test workflow&quot; button (on schedule trigger node). This will execute the workflow immediately, bypassing the schedule. <strong>Use this only in analyzer mode!</strong> It&#39;s crucial to verify that your API calls and order parameters are correct before letting it run automatically.</li></ul><p><strong>7. Monitor Execution</strong></p><ul><li>Once the workflow is active, it will run automatically at 9:20 AM IST every day.</li><li>You can monitor the executions by clicking on the &quot;Executions&quot; tab in n8n. This will show you a history of when the workflow ran and whether it was successful.</li><li>You should also see the orders appearing in your Tradeboard order book.</li></ul><p><strong>Troubleshooting</strong></p><ul><li><strong>Workflow not triggering:</strong><ul><li><strong>Is it active?</strong> Double-check that the &quot;Active&quot; toggle is switched on.</li><li><strong>Cron expression:</strong> Verify that your Cron expression is correct. You can use online Cron expression generators to test your expression.</li><li><strong>Timezone:</strong> Make absolutely sure the timezone in n8n&#39;s settings is set to &quot;Asia/Kolkata&quot; (or your correct local timezone).</li><li><strong>n8n errors:</strong> Check the n8n logs (accessible through the settings or the command line if you&#39;re running it locally) for any error messages.</li></ul></li><li><strong>Orders not placing in Tradeboard:</strong><ul><li><strong>API Key:</strong> Double-check your API key in the HTTP Request nodes.</li><li><strong>URL:</strong> Make sure the URL is the correct Tradeboard endpoint.</li><li><strong>JSON Format:</strong> Ensure your JSON body is correctly formatted. Any missing commas, brackets, or incorrect field names will cause errors.</li><li><strong>Tradeboard Logs:</strong> Check the Tradeboard logs for any error messages.</li></ul></li></ul><h4 id="why-use-n8n-for-tradeboard" tabindex="-1"><strong>Why Use n8n for Tradeboard?</strong> <a class="header-anchor" href="#why-use-n8n-for-tradeboard" aria-label="Permalink to &quot;**Why Use n8n for Tradeboard?**&quot;">​</a></h4><ul><li><strong>No-code / Low-code Automation:</strong> Simplifies complex trading workflows.</li><li><strong>Open-source &amp; Self-hosted:</strong> No expensive SaaS fees.</li><li><strong>Customizable &amp; Scalable:</strong> Adapt workflows based on trading needs.</li><li><strong>Supports Webhooks &amp; APIs:</strong> Seamless integration with Tradeboard.</li></ul>',57)])])}const w=e(g,[["render",h]]);export{b as __pageData,w as default};
